  assert.equal(totals.subtotal, 127500); // 42500 + 85000
  assert.equal(totals.discount, 2125); // Only from second line
  assert.equal(totals.vat, 26338); // VAT on 42500 (8925) + VAT on 82875 (17404) + (need to verify)
  // VAT on 42500 = 8925, VAT on 82875 = 17404
  // Total VAT = 8925 + 17404 = 26329
  assert.equal(totals.total, 151704); // 127500 - 2125 + 26329
});

