test('lineVAT with bulk discount on 0% VAT line', () => {
  const line = { qty: 10, unitPrice: 6000, discountPercent: 0, vatRate: 0 };
  // lineTotal = 60000, lineDiscount = 0, bulkDiscount = 1500, net = 58500
