test('invoiceTotals with bulk discount on 9% VAT line', () => {
  const invoice = {
    lines: [
      { qty: 20, unitPrice: 37, discountPercent: 0, vatRate: 9 }, // 740, 185 bulk, vat on 555
    ],
  };
  const totals = invoiceTotals(invoice);

  // lineTotal = 740, lineDiscount = 0, bulkDiscount = roundCents(740 * 2.5 / 100) = 19
  // net = 740 - 19 = 721
  // VAT = 721 * 9 / 100 = 64.89 → 65
  assert.equal(totals.subtotal, 740);
  assert.equal(totals.discount, 19);
  assert.equal(totals.vat, 65);
  assert.equal(totals.total, 786); // 740 - 19 + 65
});

