    voucher: { code: 'TEST', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 17404);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 95279); // 85000 - 2125 + 17404 - 5000
});

test('bulkDiscount clamped to >= 0', () => {
  // Bulk discount should never be negative
  const line = { qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 };
  assert.equal(bulkDiscount(line) >= 0, true);
});

test('lineVAT with bulk discount on 0% VAT line', () => {
  const line = { qty: 10, unitPrice: 6000, discountPercent: 0, vatRate: 0 };
  // lineTotal = 60000, lineDiscount = 0, bulkDiscount = 1500, net = 58500
  // VAT = 0
  assert.equal(lineVAT(line), 0);
});

test('invoiceTotals with bulk discount on 9% VAT line', () => {
  const invoice = {
    lines: [
      { qty: 20, unitPrice: 37, discountPercent: 0, vatRate: 9 }, // 740, 18 bulk (740 * 2.5 / 100 = 18.5 → 18)
    ],
  };
  const totals = invoiceTotals(invoice);

  // lineTotal = 740, lineDiscount = 0, bulkDiscount = roundCents(740 * 2.5 / 100) = 18 (banker's rounding)
  // net = 740 - 18 = 722
  // VAT = 722 * 9 / 100 = 64.98 → 65
  assert.equal(totals.subtotal, 740);
  assert.equal(totals.discount, 18);
  assert.equal(totals.vat, 65);
  assert.equal(totals.total, 787); // 740 - 18 + 65
});

