41	/**
42	 * Calculate the VAT for a single line: (lineTotal - lineDiscount - bulkDiscount) times vatRate / 100.
43	 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
44	 * @returns {number} VAT in cents, clamped to >= 0
45	 */
46	export function lineVAT(line) {
47	  const total = lineTotal(line);
48	  const discount = lineDiscount(line);
49	  const bulk = bulkDiscount(line);
50	  const netTotal = total - discount - bulk;
51	  const vat = roundCents((netTotal * line.vatRate) / 100);
52	  return Math.max(0, vat);
53	}
54	
55	/**
56	 * Calculate totals for an invoice.
57	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { amount: number } }} invoice
58	 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} all in cents
59	 */
60	export function invoiceTotals(invoice) {
61	  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
62	  const lineDiscounts = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
63	  const bulkDiscounts = invoice.lines.reduce((sum, line) => sum + bulkDiscount(line), 0);
64	  const discount = lineDiscounts + bulkDiscounts;
65	  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
66	  const voucher = invoice.voucher?.amount ?? 0;
67	  const total = Math.max(0, subtotal - discount + vat - voucher);
68	  return { subtotal, discount, vat, voucher, total };
69	}
