65	/**
66	 * Format cents in any supported currency.
67	 * @param {number} cents - amount in that currency's cents
68	 * @param {string} currency - currency code (EUR, USD, or GBP)
69	 * @returns {string}
70	 */
71	export function formatMoney(cents, currency) {
72	  const sign = cents < 0 ? '-' : '';
73	  const abs = Math.abs(cents);
74	  const units = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
75	  const decimalCents = String(abs % 100).padStart(2, '0');
76	  const formatted = `${units}.${decimalCents}`;
77	
78	  switch (currency) {
79	    case 'USD':
80	      return `${sign}$${formatted}`;
81	    case 'GBP':
82	      return `${sign}£${formatted}`;
83	    case 'EUR':
84	    default:
85	      return `${sign}€${formatted}`;
86	  }
87	}
