1	import { ok, fail } from './result.js';
2	import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
3	import { getProduct } from './catalogue.js';
4	import { nextInvoiceNumber } from './numbering.js';
5	import { roundCents } from './money.js';
6	import { isValidDate, calculateDueDate } from './dates.js';
7	import { lineTotal, lineDiscount, lineVAT, invoiceTotals, bulkDiscount } from './totals.js';
8	
9	// Re-export totals functions for backward compatibility
10	export { lineTotal, lineDiscount, lineVAT, invoiceTotals, bulkDiscount };
11	
12	/**
13	 * Validate a discount percent value (0-100, can be decimal).
14	 * @param {unknown} discountPercent
15	 * @returns {boolean}
16	 */
17	function isValidDiscountPercent(discountPercent) {
18	  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
19	}
20	
21	/**
22	 * Create a draft invoice.
23	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
24	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms?: string, dueDate?: string } } | { ok: false, error: string }}
25	 */
26	export function createInvoice({ customerId, issueDate, lines, terms }) {
27	  // Normalize customer ID
28	  const normalizedCustomerId = normalizeId(customerId);
29	
30	  // Validate customer exists
31	  const customerResult = getCustomer(normalizedCustomerId);
32	  if (!customerResult.ok) return customerResult;
33	
34	  const customer = customerResult.value;
35	
36	  // Validate date format and validity
37	  if (!isValidDate(issueDate)) return fail('DATE_INVALID');
38	
39	  // Validate terms if provided
40	  const effectiveTerms = terms ?? 'NET30';
41	  if (!['NET14', 'NET30', 'EOM'].includes(effectiveTerms)) {
42	    return fail('TERMS_INVALID');
43	  }
44	
45	  // Calculate due date
46	  const dueDate = calculateDueDate(issueDate, effectiveTerms);
47	
48	  // Validate lines array is not empty
49	  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');
50	
51	  // Process and validate each line
52	  const processedLines = [];
53	  for (const line of lines) {
54	    // Validate qty is a positive integer
55	    if (!Number.isInteger(line.qty) || line.qty <= 0) {
56	      return fail('QTY_INVALID');
57	    }
58	
59	    // Validate discount percent if provided
60	    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
61	      return fail('DISCOUNT_INVALID');
62	    }
63	
64	    // Get product from catalogue
65	    const productResult = getProduct(line.sku);
66	    if (!productResult.ok) return productResult;
67	
68	    const product = productResult.value;
69	    const processedLine = {
70	      sku: line.sku,
71	      name: product.name,
72	      qty: line.qty,
73	      unitPrice: product.unitPrice,
74	      vatRate: product.vatRate,
75	    };
76	
77	    // Apply discount: line's own discountPercent wins, otherwise use tier discount
78	    if (line.discountPercent !== undefined) {
79	      processedLine.discountPercent = line.discountPercent;
80	    } else {
81	      const tierDiscount = TIER_DISCOUNTS[customer.tier];
82	      if (tierDiscount > 0) {
83	        processedLine.discountPercent = tierDiscount;
84	      }
85	    }
86	
87	    processedLines.push(processedLine);
88	  }
89	
90	  const invoice = {
91	    customerId: normalizedCustomerId,
92	    issueDate,
93	    status: 'draft',
94	    lines: processedLines,
95	    terms: effectiveTerms,
96	    dueDate,
97	  };
98	
99	  return ok(invoice);
100	}

1	import { readFileSync } from 'node:fs';
2	import { ok, fail } from './result.js';
3	
4	const CUSTOMERS = JSON.parse(readFileSync(new URL('../data/customers.json', import.meta.url), 'utf8'));
5	
6	/**
7	 * Discount percentages by customer tier.
8	 */
9	export const TIER_DISCOUNTS = {
10	  gold: 5,
11	  silver: 2.5,
12	  standard: 0,
13	};
14	
15	/**
16	 * Normalize a customer ID: trim whitespace and convert to uppercase.
17	 * @param {string} id
18	 * @returns {string}
19	 */
20	export function normalizeId(id) {
21	  return String(id).trim().toUpperCase();
22	}
23	
24	/**
25	 * All customers: { id, name, email, country, tier }.
26	 */
27	export function listCustomers() {
28	  return CUSTOMERS.map((c) => ({ ...c }));
29	}
30	
31	/**
32	 * One customer by id.
33	 * @param {string} id
34	 */
35	export function getCustomer(id) {
36	  const normalizedId = normalizeId(id);
37	  const c = CUSTOMERS.find((x) => x.id === normalizedId);
38	  return c ? ok({ ...c }) : fail('CUSTOMER_NOT_FOUND');
39	}
40	
41	/**
42	 * Check a customer record before it is stored.
43	 * @param {{ id?: string, name?: string, email?: string }} c
44	 */
45	export function validateCustomer(c) {
46	  if (!c || !c.id || !c.name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.email ?? '')) return fail('CUSTOMER_INVALID');
47	  return ok({ ...c });
48	}
49	
50	/**
51	 * Merge two customers: delete fromId and reassign its invoices to intoId.
52	 * @param {Array} customers
53	 * @param {Array} invoices
54	 * @param {string} fromId - customer to merge from (will be deleted)
55	 * @param {string} intoId - customer to merge into
56	 * @returns {{ ok: true, value: { customers: Array, invoices: Array } } | { ok: false, error: string }}
57	 */
58	export function mergeCustomers(customers, invoices, fromId, intoId) {
59	  const normalizedFromId = normalizeId(fromId);
60	  const normalizedIntoId = normalizeId(intoId);
61	
62	  // Check if same customer
63	  if (normalizedFromId === normalizedIntoId) {
64	    return fail('SAME_CUSTOMER');
65	  }
66	
67	  // Check if both customers exist
68	  const fromCustomer = customers.find((c) => normalizeId(c.id) === normalizedFromId);
69	  const intoCustomer = customers.find((c) => normalizeId(c.id) === normalizedIntoId);
70	
71	  if (!fromCustomer || !intoCustomer) {
72	    return fail('CUSTOMER_NOT_FOUND');
73	  }
74	
75	  // Remove fromCustomer from customers array (return new array)
76	  const newCustomers = customers.filter((c) => normalizeId(c.id) !== normalizedFromId);
77	
78	  // Update invoices: reassign all invoices from fromId to intoId (return new array)
79	  const newInvoices = invoices.map((invoice) => {
80	    if (normalizeId(invoice.customerId) === normalizedFromId) {
81	      return { ...invoice, customerId: normalizedIntoId };
82	    }
83	    return invoice;
84	  });
85	
86	  return ok({ customers: newCustomers, invoices: newInvoices });
87	}
