1	import { ok, fail } from './result.js';
2	
3	/**
4	 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
5	 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
6	 * @param {number} x
7	 * @returns {number}
8	 */
9	export function roundCents(x) {
10	  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
11	  const floor = Math.floor(r);
12	  const diff = r - floor;
13	  if (diff > 0.5) return floor + 1;
14	  if (diff < 0.5) return floor === 0 ? 0 : floor;
15	  return floor % 2 === 0 ? floor : floor + 1;
16	}
17	
18	/**
19	 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
20	 * @param {number} cents
21	 * @returns {string}
22	 */
23	export function formatEuros(cents) {
24	  const sign = cents < 0 ? '-' : '';
25	  const abs = Math.abs(cents);
26	  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
27	  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
28	}
29	
30	/**
31	 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
32	 * @param {string} text
33	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
34	 */
35	export function parseEuros(text) {
36	  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
37	  if (!m) return fail('AMOUNT_INVALID');
38	  const euros = Number(m[1].replace(/,/g, ''));
39	  const cents = Number((m[2] ?? '').padEnd(2, '0'));
40	  return ok(euros * 100 + cents);
41	}
42	
43	export const RATES = {
44	  EUR: 1,
45	  USD: 1.085,
46	  GBP: 0.8425,
47	};
48	
49	/**
50	 * Convert EUR cents to another currency.
51	 * @param {number} cents - amount in EUR cents
52	 * @param {string} currency - target currency code (EUR, USD, or GBP)
53	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
54	 */
55	export function convert(cents, currency) {
56	  if (!RATES[currency]) {
57	    return fail('UNKNOWN_CURRENCY');
58	  }
59	
60	  const rate = RATES[currency];
61	  const converted = roundCents(cents * rate);
62	  return ok(converted);
63	}
64	
65	/**
66	 * Format cents in any supported currency.
67	 * @param {number} cents - amount in that currency's cents
68	 * @param {string} currency - currency code (EUR, USD, or GBP)
69	 * @returns {string}
70	 */
71	export function formatMoney(cents, currency) {
72	  const sign = cents < 0 ? '-' : '';
73	  const abs = Math.abs(cents);
74	  const units = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
75	  const decimalCents = String(abs % 100).padStart(2, '0');
76	  const formatted = `${units}.${decimalCents}`;
77	
78	  switch (currency) {
79	    case 'USD':
80	      return `${sign}$${formatted}`;
81	    case 'GBP':
82	      return `${sign}£${formatted}`;
83	    case 'EUR':
84	    default:
85	      return `${sign}€${formatted}`;
86	  }
87	}
