import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount, lineVAT, applyVoucher } from '../src/invoices.js';
import { TIER_DISCOUNTS } from '../src/customers.js';

test('createInvoice creates a draft invoice with valid data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2025-10-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);

  const line = result.value.lines[0];
  assert.equal(line.sku, 'DES-HOUR');
  assert.equal(line.name, 'Design work (hour)');
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, 8500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice normalizes customer ID before storing', () => {
  const result = createInvoice({
    customerId: 'c-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice accepts customer ID with whitespace', () => {
  const result = createInvoice({
    customerId: ' C-001 ',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice accepts mixed case customer ID with whitespace', () => {
  const result = createInvoice({
    customerId: ' c-007 ',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-007');
  assert.equal(result.value.lines[0].discountPercent, undefined); // standard tier
});

test('createInvoice sets default terms to NET30', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2025-11-14');
});

test('createInvoice accepts NET14 terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET14');
  assert.equal(result.value.dueDate, '2025-10-29');
});

test('createInvoice accepts NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2025-11-14');
});

test('createInvoice accepts EOM terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'EOM');
  assert.equal(result.value.dueDate, '2025-10-31');
});

test('createInvoice EOM works for different months', () => {
  // February in non-leap year
  let result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(result.value.dueDate, '2025-02-28');

  // February in leap year
  result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(result.value.dueDate, '2024-02-29');

  // December (year boundary)
  result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-12-20',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(result.value.dueDate, '2025-12-31');
});

test('createInvoice rejects invalid terms', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2025-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
      terms: 'NET60',
    }),
    { ok: false, error: 'TERMS_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2025-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
      terms: 'INVALID',
    }),
    { ok: false, error: 'TERMS_INVALID' }
  );
});

test('invoiceTotals includes voucher field', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // €514.25
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals total formula with voucher: subtotal - discount + vat - voucher', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }], // €850 - bulk 2.5% €21.25 = €828.75 + VAT €174.04 = €1002.79
  }).value;

  let totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 17404);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 100279);

  // Apply voucher
  const result = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  invoice = result.value;

  totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
