    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 20 }], // €850, 20% discount = €170 - bulk 2.5% €17 = €187, net €663, VAT €139.23, total €802.23
    terms: 'NET14',
