  assert.equal(lines[1], 'INV-2025-0001,"Smith, Jones & Partners",2025-10-15,2025-10-29,issued,85.00,0.00,17.85,102.85,102.85');
});

test('exportCsv escapes double quotes in customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-006', // Customer with quote in name: Marlow "The Print Shop"
    issueDate: '2025-10-15',
