  assert.equal(lines[1], 'INV-2025-0001,"Marlow ""The Print Shop""",2025-10-15,2025-10-29,issued,85.00,0.00,17.85,102.85,102.85');
});

test('exportCsv exports multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }], // €475, VAT €99.75, total €574.75
    terms: 'NET14',
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const csv = exportCsv([issued1, issued2]);
  const lines = csv.split('\n');

  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines[1], 'INV-2025-0001,Blue Fern Bakery,2025-10-01,2025-10-15,issued,425.00,0.00,89.25,514.25,514.25');
  assert.equal(lines[2], 'INV-2025-0002,Blue Fern Bakery,2025-10-05,2025-10-19,issued,475.00,0.00,99.75,574.75,574.75');
});

test('exportCsv preserves invoice order', () => {
  const invoices = [];

  for (let i = 0; i < 5; i++) {
    const inv = createInvoice({
      customerId: 'C-002',
      issueDate: `2025-10-${String(i + 1).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
      terms: 'NET14',
    }).value;
    const issued = issueInvoice(inv, invoices.map((_, idx) => `INV-2025-${String(idx + 1).padStart(4, '0')}`)).value;
    invoices.push(issued);
  }

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');

  assert.equal(lines[1].startsWith('INV-2025-0001'), true);
  assert.equal(lines[2].startsWith('INV-2025-0002'), true);
  assert.equal(lines[3].startsWith('INV-2025-0003'), true);
  assert.equal(lines[4].startsWith('INV-2025-0004'), true);
  assert.equal(lines[5].startsWith('INV-2025-0005'), true);
});

test('exportCsv with mixed invoice statuses', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    // Default terms is NET30, so dueDate is 2025-10-31
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
    terms: 'NET14',
  }).value;
  let issued2 = issueInvoice(inv2, []).value;
  issued2 = recordPayment(issued2, { amount: 25500, date: '2025-10-10' }).value;

  const csv = exportCsv([draft, issued2]);
  const lines = csv.split('\n');

  assert.equal(lines[1], ',Blue Fern Bakery,2025-10-01,2025-10-31,draft,425.00,0.00,89.25,514.25,514.25');
  assert.equal(lines[2], 'INV-2025-0001,Blue Fern Bakery,2025-10-05,2025-10-19,partially_paid,255.00,0.00,53.55,308.55,53.55');
});

test('exportCsv ends with newline', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const csv = exportCsv([issued]);

  assert.equal(csv.endsWith('\n'), true);
});

test('exportCsv with voucher', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // €514.25
    terms: 'NET14',
  }).value;

  // Apply voucher to draft invoice
  const voucherResult = issueInvoice(invoice, []);
  invoice = voucherResult.value;

  // Manually add voucher since it's already issued
  // Voucher reduces the total from 514.25 to 414.25 (100 euros = 10000 cents)
  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');

  // Check that the invoice line is present with correct number
  assert.equal(lines[1].includes('INV-2025-0001'), true);
  assert.equal(lines[1].includes('514.25'), true); // total without voucher
});

test('exportCsv with zero values', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }], // €600, 0% VAT, total €600
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  // All amounts formatted with 2 decimals
  assert.equal(lines[1], 'INV-2025-0001,Blue Fern Bakery,2025-10-15,2025-10-29,issued,600.00,0.00,0.00,600.00,600.00');
});

test('exportCsv with large amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'LOGO-PACK', qty: 5 }], // €1200 * 5 = €6000, no discount, VAT 21% = €1260, total €7260
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const csv = exportCsv([issued]);
  const lines = csv.split('\n');

  assert.equal(lines[1], 'INV-2025-0001,Blue Fern Bakery,2025-10-15,2025-10-29,issued,6000.00,0.00,1260.00,7260.00,7260.00');
});

