test('vatSummary with multiple VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // €85 * 5 = €425, VAT 21% = €89.25
      { sku: 'PRINT-A4', qty: 30 }, // €37 * 30 = €1110 cents, VAT 9% = €99.90 → 100
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result.length, 2);
  // Sorted by rate descending
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 42500);
  assert.equal(result[0].vat, 8925);
  assert.equal(result[1].rate, 9);
  assert.equal(result[1].base, 1110);
  assert.equal(result[1].vat, 100);
});

test('vatSummary sorted by rate descending', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'PRINT-A4', qty: 10 }, // 9% VAT
      { sku: 'DES-HOUR', qty: 5 }, // 21% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result.length, 3);
  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
  assert.equal(result[2].rate, 0);
});

test('vatSummary with 0% VAT rate', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 2 }], // €600 * 2 = €1200, VAT 0%
  }).value;
  const issued = issueInvoice(invoice, []).value;

